import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise OSError("Script path does not exist")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    start_time = time.time()
    cpu_usage = 0.0
    memory_usage = 0
    try:
        while proc.poll() is None and (time.time() - start_time) < timeout:
            try:
                p = psutil.Process(proc.pid)
                with p.oneshot():
                    cpu_times = p.cpu_times()
                    mem_info = p.memory_info()
                cpu_usage = cpu_times.user + cpu_times.system
                memory_usage = mem_info.rss
                time.sleep(0.1)
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
        if proc.poll() is None:
            proc.terminate()
            time.sleep(0.5)
            if proc.poll() is None:
                proc.kill()
    except Exception:
        if proc.poll() is None:
            proc.kill()
    finally:
        stdout, stderr = proc.communicate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
